// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok = true;
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(success && c.owner() == newOwner && actor == address(this));
        } catch {
            ok = false;
            assertTrue(!ok && c.owner() != newOwner);
        }
    }
}
